"use strict";(globalThis.webpackChunkmy_book=globalThis.webpackChunkmy_book||[]).push([[8285],{4223:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"welcome","metadata":{"permalink":"/Physical-AI-Humanoid-Robotics-book/blog/welcome","editUrl":"https://github.com/syedjalees/Physical-AI-Humanoid-Robotics-book/tree/main/blog/2021-08-26-welcome/index.md","source":"@site/blog/2021-08-26-welcome/index.md","title":"Welcome to My AI-Native Hackathon Blog","description":"Welcome to the blog documenting my journey in the Panaversity Physical AI & Humanoid Robotics Hackathon!","date":"2021-08-26T00:00:00.000Z","tags":[{"inline":false,"label":"AI Native","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/tags/ai-native","description":"AI-Native textbook and agent-powered learning content."},{"inline":false,"label":"Hackathon","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/tags/hackathon","description":"Posts related to the Panaversity Physical AI & Humanoid Robotics Hackathon."},{"inline":false,"label":"Docusaurus","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/tags/docusaurus","description":"Tutorials and content about building sites with Docusaurus."}],"readingTime":1.26,"hasTruncateMarker":true,"authors":[{"name":"SAYYED JALEES","title":"AI-Native Textbook Developer | Panaversity Hackathon Participant","url":"https://porfolio-jalees.vercel.app/","page":{"permalink":"/Physical-AI-Humanoid-Robotics-book/blog/authors/sayyed-jalees"},"socials":{"x":"https://x.com/your-twitter","linkedin":"https://www.linkedin.com/in/sayyed-jalees/","github":"https://github.com/syedjalees"},"imageURL":"https://media.licdn.com/dms/image/v2/D5603AQG85diWaXwiqg/profile-displayphoto-shrink_400_400/B56ZcHv3LbHwAg-/0/1748181677438?e=2147483647&v=beta&t=i3X96lrte4tMhMbO7f71b03UmYdTJaOm4dykQvavpU0","key":"SAYYED JALEES"}],"frontMatter":{"slug":"welcome","title":"Welcome to My AI-Native Hackathon Blog","authors":["SAYYED JALEES"],"tags":["ai-native","hackathon","docusaurus"]},"unlisted":false,"nextItem":{"title":"Exploring MDX + React in My AI-Native Textbook Project","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/mdx-blog-post"}},"content":"Welcome to the blog documenting my journey in the **Panaversity Physical AI & Humanoid Robotics Hackathon**!  \\nThis blog is powered by the Docusaurus **Blog Plugin**, which makes it incredibly simple to publish posts, showcase progress, share updates, and integrate interactive MDX-powered content.\\n\\n\x3c!-- truncate --\x3e\\n\\n## \ud83d\ude80 Getting Started with the Blog\\n\\nSetting up a blog in Docusaurus is easy \u2014 you just add Markdown or MDX files inside the `blog` directory.\\n\\nEach post can include:\\n\\n- A `slug` for clean URLs  \\n- Authors from `authors.yaml`  \\n- Tags for categorization and filtering  \\n- MDX components for interactivity  \\n- Images stored next to the post folder  \\n\\nFor example, your blog post structure can look like:\\n\\n- `2021-08-26-welcome.md`\\n- `2021-08-26-welcome/index.md`  \\n- With images stored in the same folder (like the one below)\\n\\n![Docusaurus Plushie](./docusaurus-plushie-banner.jpeg)\\n\\n---\\n\\n## \ud83e\udde0 Why This Blog Exists\\n\\nThroughout the hackathon, I\u2019m using this space to document:\\n\\n- My progress building an **AI-native textbook**\\n- Integrating a **RAG-based AI chatbot**\\n- Experiments with **Claude Code** & **Spec-Kit Plus**\\n- Personalization features & Urdu translation buttons\\n- Docusaurus tips, MDX tricks, and integrations  \\n\\nThis will help me track my development journey and share insights with others following along.\\n\\n---\\n\\n## \ud83c\udff7\ufe0f Tags & Metadata\\n\\nDocusaurus supports tags for smart filtering and organization.  \\nYou can define your tags in the `tags.yml` file, and assign them to posts like this one.\\n\\n---\\n\\n## \u274c Don\u2019t Want a Blog?\\n\\nIf you prefer a docs-only textbook:  \\nJust delete the entire `/blog` directory and set `blog: false` inside your Docusaurus config.\\n\\n---\\n\\nThanks for stopping by!  \\nMore updates, demos, and AI-powered experiments coming soon. \ud83d\ude80"},{"id":"mdx-blog-post","metadata":{"permalink":"/Physical-AI-Humanoid-Robotics-book/blog/mdx-blog-post","editUrl":"https://github.com/syedjalees/Physical-AI-Humanoid-Robotics-book/tree/main/blog/2021-08-01-mdx-blog-post.mdx","source":"@site/blog/2021-08-01-mdx-blog-post.mdx","title":"Exploring MDX + React in My AI-Native Textbook Project","description":"Blog posts in Docusaurus are extremely powerful \u2014 especially because they support full MDX, letting you mix Markdown and React components inside a single article.","date":"2021-08-01T00:00:00.000Z","tags":[{"inline":false,"label":"Docusaurus","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/tags/docusaurus","description":"Tutorials and content about building sites with Docusaurus."},{"inline":false,"label":"MDX","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/tags/mdx","description":"Posts showcasing MDX + React interactivity."},{"inline":true,"label":"react","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/tags/react"},{"inline":false,"label":"Hackathon","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/tags/hackathon","description":"Posts related to the Panaversity Physical AI & Humanoid Robotics Hackathon."}],"readingTime":0.83,"hasTruncateMarker":true,"authors":[{"name":"SAYYED JALEES","title":"AI-Native Textbook Developer | Panaversity Hackathon Participant","url":"https://porfolio-jalees.vercel.app/","page":{"permalink":"/Physical-AI-Humanoid-Robotics-book/blog/authors/sayyed-jalees"},"socials":{"x":"https://x.com/your-twitter","linkedin":"https://www.linkedin.com/in/sayyed-jalees/","github":"https://github.com/syedjalees"},"imageURL":"https://media.licdn.com/dms/image/v2/D5603AQG85diWaXwiqg/profile-displayphoto-shrink_400_400/B56ZcHv3LbHwAg-/0/1748181677438?e=2147483647&v=beta&t=i3X96lrte4tMhMbO7f71b03UmYdTJaOm4dykQvavpU0","key":"SAYYED JALEES"}],"frontMatter":{"slug":"mdx-blog-post","title":"Exploring MDX + React in My AI-Native Textbook Project","authors":["SAYYED JALEES"],"tags":["docusaurus","mdx","react","hackathon"]},"unlisted":false,"prevItem":{"title":"Welcome to My AI-Native Hackathon Blog","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/welcome"},"nextItem":{"title":"My Complete Journey Building an AI-Native Textbook","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/long-blog-post"}},"content":"Blog posts in Docusaurus are extremely powerful \u2014 especially because they support full **MDX**, letting you mix Markdown and React components inside a single article.\\n\\nThis post demonstrates how I\u2019m using **MDX**, **interactive elements**, and **custom components** in my AI-Native textbook for the Panaversity Hackathon.\\n\\n:::tip \u2728 MDX Superpower\\nMDX lets you write content like normal Markdown **while embedding live React components** inside your post.\\n\\nThis makes your blog interactive, dynamic, and perfect for technical demos.\\n:::\\n\\n{/* truncate */}\\n\\n## \ud83d\ude80 Why MDX Matters in the Hackathon\\n\\nSince the final deliverable is an AI-native technical textbook, having MDX support allows:\\n\\n- Interactive examples inside chapters  \\n- Live UI elements for AI features  \\n- Buttons for personalization + Urdu translation  \\n- Custom JSX blocks for explanations  \\n- React-based visualizations  \\n\\nMDX turns your textbook into an **interactive learning platform**, not just a static document.\\n\\n---\\n\\n## \ud83c\udfae Interactive Example: React Button\\n\\nBelow is a simple demo showing how React components work directly inside a blog post.\\n\\n```jsx\\n<button onClick={() => alert(\'You clicked a React-powered MDX button!\')}>\\n  Click me!\\n</button>"},{"id":"long-blog-post","metadata":{"permalink":"/Physical-AI-Humanoid-Robotics-book/blog/long-blog-post","editUrl":"https://github.com/syedjalees/Physical-AI-Humanoid-Robotics-book/tree/main/blog/2019-05-29-long-blog-post.md","source":"@site/blog/2019-05-29-long-blog-post.md","title":"My Complete Journey Building an AI-Native Textbook","description":"This is a detailed breakdown of my experience participating in the Panaversity Hackathon: AI-Native Textbook for Physical AI & Humanoid Robotics.","date":"2019-05-29T00:00:00.000Z","tags":[{"inline":false,"label":"AI Native","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/tags/ai-native","description":"AI-Native textbook and agent-powered learning content."},{"inline":false,"label":"Hackathon","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/tags/hackathon","description":"Posts related to the Panaversity Physical AI & Humanoid Robotics Hackathon."},{"inline":false,"label":"Docusaurus","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/tags/docusaurus","description":"Tutorials and content about building sites with Docusaurus."},{"inline":true,"label":"panaversity","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/tags/panaversity"}],"readingTime":2.33,"hasTruncateMarker":true,"authors":[{"name":"SAYYED JALEES","title":"AI-Native Textbook Developer | Panaversity Hackathon Participant","url":"https://porfolio-jalees.vercel.app/","page":{"permalink":"/Physical-AI-Humanoid-Robotics-book/blog/authors/sayyed-jalees"},"socials":{"x":"https://x.com/your-twitter","linkedin":"https://www.linkedin.com/in/sayyed-jalees/","github":"https://github.com/syedjalees"},"imageURL":"https://media.licdn.com/dms/image/v2/D5603AQG85diWaXwiqg/profile-displayphoto-shrink_400_400/B56ZcHv3LbHwAg-/0/1748181677438?e=2147483647&v=beta&t=i3X96lrte4tMhMbO7f71b03UmYdTJaOm4dykQvavpU0","key":"SAYYED JALEES"}],"frontMatter":{"slug":"long-blog-post","title":"My Complete Journey Building an AI-Native Textbook","authors":"SAYYED JALEES","tags":["ai-native","hackathon","docusaurus","panaversity"]},"unlisted":false,"prevItem":{"title":"Exploring MDX + React in My AI-Native Textbook Project","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/mdx-blog-post"},"nextItem":{"title":"Welcome to My AI-Native Hackathon Journey","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/first-blog-post"}},"content":"This is a detailed breakdown of my experience participating in the **Panaversity Hackathon: AI-Native Textbook for Physical AI & Humanoid Robotics**.  \\nIn this long-form blog, I\u2019ll walk through my workflow, tools, challenges, and the major breakthroughs I encountered while building a fully automated AI-powered learning system.\\n\\nUse a `\x3c!-- truncate --\x3e` comment to limit how much appears in the blog list.\\n\\n\x3c!-- truncate --\x3e\\n\\n## \ud83d\ude80 Getting Started \u2014 Understanding the Vision\\n\\nThe hackathon is not just a coding challenge \u2014 it\'s a blueprint for how future technical content will be created: AI-generated, agent-enhanced, personalized, and interactive.  \\nMy objective was clear:\\n\\n- Build a polished Docusaurus textbook  \\n- Use Spec-Kit Plus & Claude Code to auto-generate content  \\n- Integrate a RAG chatbot powered by OpenAI Agents  \\n- Add database + vector search via NeonDB & Qdrant  \\n- Introduce chapter personalization & Urdu translation  \\n- Explore reusable intelligence through subagents and agent skills  \\n\\n---\\n\\n## \ud83e\udde9 Phase 1 \u2014 Setting Up the Project Scaffold\\n\\nI began by initializing a fresh **Docusaurus** project.  \\nFrom file structure to plugin setup, everything needed to be optimized so that the book could grow automatically using Spec-Kit Plus.\\n\\nKey steps included:\\n\\n- Installing dependencies  \\n- Creating initial docs/pages/folders  \\n- Connecting GitHub Pages deployment  \\n- Ensuring the blog and docs systems were clean and organized  \\n\\nOnce this was done, I connected Claude Code to the repo.\\n\\n---\\n\\n## \ud83e\udd16 Phase 2 \u2014 AI-Driven Book Creation (Spec-Kit + Claude Code)\\n\\nThis was the real game-changer.  \\nUsing the Spec-Kit Plus architecture, I generated:\\n\\n- Course outlines  \\n- Progressive chapters  \\n- Code examples  \\n- Diagrams  \\n- Glossaries  \\n- Index files  \\n\\nClaude Code helped automate formatting, summaries, cleanup, and content alignment.\\n\\nThe result:  \\nA fully structured AI-generated textbook evolving in real time.\\n\\n---\\n\\n## \ud83d\udd0d Phase 3 \u2014 Building the RAG Chatbot\\n\\nTo power question-answering inside the book, I set up:\\n\\n- **FastAPI backend**  \\n- **Neon Serverless Postgres** for metadata  \\n- **Qdrant Cloud** for vector embeddings  \\n- **OpenAI Agents / ChatKit SDK** for intelligent reasoning  \\n\\nThe chatbot can:\\n\\n- Answer queries based on full textbook content  \\n- Work with selected text snippets  \\n- Provide contextual suggestions  \\n- Maintain conversation memory  \\n\\n---\\n\\n## \ud83c\udfa8 Phase 4 \u2014 Personalization & Urdu Translation\\n\\nI implemented two buttons at the top of every chapter:\\n\\n### \u2714\ufe0f **Personalize Content**  \\nAdjusts complexity, examples, tone, and learning depth based on user background.\\n\\n### \u2714\ufe0f **Translate to Urdu**  \\nInstantly converts the entire chapter into fluent, academic-level Urdu.\\n\\nBoth features required front-end customization + agent logic.\\n\\n---\\n\\n## \ud83e\udde0 Phase 5 \u2014 Reusable Intelligence with Subagents\\n\\nUsing Claude Code, I experimented with:\\n\\n- Subagents for code generation  \\n- Subagents for translation  \\n- Subagents for summarization  \\n- Skills that could be reused across chapters  \\n\\nThis made content creation **faster, smarter, and modular**.\\n\\n---\\n\\n## \ud83d\udcc8 Final Thoughts \u2014 What I Learned\\n\\nThis hackathon challenged me to think beyond traditional coding.  \\nI learned to:\\n\\n- Combine multiple AI tools  \\n- Automate textbook creation  \\n- Build RAG-based intelligent systems  \\n- Personalize learning experiences  \\n- Deploy modern AI-powered platforms  \\n\\nThis project is just the beginning \u2014 the future of education is AI-native.\\n\\nStay tuned \u2014 many upgrades coming soon! \ud83d\ude80"},{"id":"first-blog-post","metadata":{"permalink":"/Physical-AI-Humanoid-Robotics-book/blog/first-blog-post","editUrl":"https://github.com/syedjalees/Physical-AI-Humanoid-Robotics-book/tree/main/blog/2019-05-28-first-blog-post.md","source":"@site/blog/2019-05-28-first-blog-post.md","title":"Welcome to My AI-Native Hackathon Journey","description":"The future of learning is shifting toward AI-native education, where textbooks, courses, and platforms are powered by intelligent agents. This blog marks the beginning of my journey in the Panaversity Physical AI & Humanoid Robotics Hackathon \u2014 a challenge designed to push the boundaries of how we create, publish, and interact with technical knowledge.","date":"2019-05-28T00:00:00.000Z","tags":[{"inline":false,"label":"Hackathon","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/tags/hackathon","description":"Posts related to the Panaversity Physical AI & Humanoid Robotics Hackathon."},{"inline":false,"label":"Docusaurus","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/tags/docusaurus","description":"Tutorials and content about building sites with Docusaurus."},{"inline":false,"label":"AI Native","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/tags/ai-native","description":"AI-Native textbook and agent-powered learning content."},{"inline":true,"label":"panaversity","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/tags/panaversity"}],"readingTime":0.81,"hasTruncateMarker":true,"authors":[{"name":"SAYYED JALEES","title":"AI-Native Textbook Developer | Panaversity Hackathon Participant","url":"https://porfolio-jalees.vercel.app/","page":{"permalink":"/Physical-AI-Humanoid-Robotics-book/blog/authors/sayyed-jalees"},"socials":{"x":"https://x.com/your-twitter","linkedin":"https://www.linkedin.com/in/sayyed-jalees/","github":"https://github.com/syedjalees"},"imageURL":"https://media.licdn.com/dms/image/v2/D5603AQG85diWaXwiqg/profile-displayphoto-shrink_400_400/B56ZcHv3LbHwAg-/0/1748181677438?e=2147483647&v=beta&t=i3X96lrte4tMhMbO7f71b03UmYdTJaOm4dykQvavpU0","key":"SAYYED JALEES"}],"frontMatter":{"slug":"first-blog-post","title":"Welcome to My AI-Native Hackathon Journey","authors":["SAYYED JALEES"],"tags":["hackathon","docusaurus","ai-native","panaversity"]},"unlisted":false,"prevItem":{"title":"My Complete Journey Building an AI-Native Textbook","permalink":"/Physical-AI-Humanoid-Robotics-book/blog/long-blog-post"}},"content":"The future of learning is shifting toward **AI-native education**, where textbooks, courses, and platforms are powered by intelligent agents. This blog marks the beginning of my journey in the **Panaversity Physical AI & Humanoid Robotics Hackathon** \u2014 a challenge designed to push the boundaries of how we create, publish, and interact with technical knowledge.\\n\\n\x3c!-- truncate --\x3e\\n\\nOver the next few days, I\u2019ll be building a complete **AI-generated textbook** using Spec-Kit Plus and Claude Code, deploying it with **Docusaurus**, and integrating a fully functional **RAG-powered chatbot** that can answer questions from the book in real time.\\n\\nSome major goals of this project include:\\n\\n- Building a polished AI-native textbook  \\n- Deploying it to GitHub Pages  \\n- Adding a RAG chatbot using OpenAI Agents, FastAPI, Qdrant, and NeonDB  \\n- Enabling personalized and Urdu-translated chapters  \\n- Exploring multi-agent workflows and reusable intelligence  \\n\\nThis blog will document my progress, challenges, learnings, and the evolution of the project as I move forward.  \\n**Stay tuned \u2014 big things are coming! \ud83d\ude80**"}]}}')}}]);